theme.customCSS:
.access-card {
border: 1px solid var(--primary);
border-radius: var(--radius-2xl); 
background-color: color-mix(in oklab, var(--card) 30%, transparent);}

/* Cartes des piliers en chevauchement sur le hero : aucune section n'expose
   d'offset negatif, c'est le seul levier sans toucher au moteur. */
#piliers { margin-top: -4.5rem; position: relative; z-index: 20; }
@media (max-width: 1023px) { #piliers { margin-top: -2rem; } }

/* Bande des searchHeader : suivre le theme du site plutot que le turquoise
   code en dur dans src/index-equipements-sportifs.css, feuille PARTAGEE avec
   equipementsSportifs974 et saintpaulSport1 — donc intouchable ici.
   `:root:root` passe devant elle quel que soit l'ordre d'injection. */
:root:root { --gradient-section: linear-gradient(135deg, var(--primary), var(--ring)); }

/* Bande « Ressources de pilotage ». Elle doit rester SOMBRE dans les deux
   modes : en dark `--primary` s'eclaircit et la bande virait au bleu vif.
   D'ou deux variables locales, seules a changer d'un mode a l'autre. */
#ressources { --band-bg: var(--primary); --band-fg: var(--primary-foreground); }
.dark #ressources { --band-bg: var(--sidebar); --band-fg: var(--foreground); }
#ressources { background-color: var(--band-bg); }

/* Les sections imbriquees posent `text-primary` (content) et `text-foreground`
   (action-tiles), invisibles sur ce fond ; un selecteur d'ID passe devant. */
#ressources h2, #ressources h3, #ressources p, #ressources span, #ressources a {
  color: var(--band-fg); }
#ressources .text-muted-foreground {
  color: color-mix(in oklab, var(--band-fg) 75%, transparent); }

/* Tuiles d'acces : `bg-accent/20` (jaune) sur ce fond bleu vire au kaki.
   Voile clair a la place, l'icone restant en accent. */
#ressources a > button {
  background-color: color-mix(in oklab, var(--band-fg) 10%, transparent);
  border-color: color-mix(in oklab, var(--band-fg) 28%, transparent); }
#ressources a > button:hover {
  background-color: color-mix(in oklab, var(--band-fg) 18%, transparent); }
